mapper.select:
/* SystemMngMapper.selectAlarm : 알림톡 조회 */
	SELECT
		 JOB_TYPE
		,(SELECT LABEL_NAME FROM TB_MMS_MANAGEMENT WHERE TEMPLATE_TYPE = JOB_TYPE AND TEMPLATE_CODE = JOB_CODE) AS JOB_TYPE_NAME
		,ALARM_ATTN_ID
		,CONVERT(VARCHAR(16), SEND_DATE_TIME, 120) AS SEND_DATE_TIME
		,BEFORE_VALUE
		,AFTER_VALUE
		,CONVERT(VARCHAR(16), DATEADD(hh, -9, RECV_DATE_TIME), 120) AS RECV_DATE_TIME
	FROM TB_SMS_ALARM
	WHERE ENT_CODE = #{entCode}


	AND REF_JOB_NO = #{refJobNo}


	AND SEQ_NO_ID = #{seqNoId}

mapper.delete:
/* SystemMngMapper.deleteAlarm : 알림톡 삭제 */
	DELETE TB_SMS_ALARM
	WHERE ENT_CODE = #{entCode}


	AND REF_JOB_NO = #{refJobNo}


	AND SEQ_NO_ID = #{seqNoId}

mapper.select:
/* SystemMngMapper.selectInterfaceKeyList : InterfaceKey List */
SELECT ENT_CODE ,CUSTOMER_CODE ,ACCESS_KEY ,USE_YN ,REGISTER_USER_ID ,REGISTER_DATE_TIME ,UPDATE_USER_ID ,UPDATE_DATE_TIME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = interface.ENT_CODE AND USER_ID = interface.REGISTER_USER_ID) AS REGISTER_USER_NAME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = interface.ENT_CODE AND USER_ID = interface.UPDATE_USER_ID) AS UPDATE_USER_NAME ,ISNULL(ORDER_CNT,0) AS ORDER_CNT ,ISNULL(DELIVERY_CODE_CNT,0) AS DELIVERY_CODE_CNT FROM TB_SMS_INTERFACE_INFO interface WHERE 1 = 1
AND interface.ENT_CODE = #{srchEntCode}
AND interface.CUSTOMER_CODE = #{srchCustomerCode}
AND interface.USE_YN = #{srchUseYn}
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))

