/* SystemMngMapper.selectMonthlyCountList : 월별건수 List 조회 */
SELECT ENT_CODE ,OD_YYMM ,TOT_CNT ,AO_CNT ,AI_CNT ,OO_CNT ,OI_CNT ,KTNET_CNT ,KCNET_CNT ,KLNET_CNT ,API_TOT_CNT ,API_AO_CNT ,API_AI_CNT ,API_OO_CNT ,API_OI_CNT ,API_HANJIN_CNT ,API_KOREX_CNT ,ISNULL(API_TRACKING_CNT,0) AS API_TRACKING_CNT FROM TB_MIS_MONTHLY_VOLUME mv WHERE OD_YYMM >= #{srchStartDate} AND OD_YYMM <= #{srchEndDate}
AND mv.ENT_CODE = #{srchEntCode}

/* SystemMngMapper.selectMonthlyUserCountList : 월별 사용자및업체 건수 List 조회 */

	SELECT
		 ENT_CODE
		,OD_YYMM
		,TOT_CNT
		,AO_CNT
		,AI_CNT
		,OO_CNT
		,OI_CNT
	FROM TB_MIS_MONTHLY_VOLUME mv
	WHERE OD_YYMM >= #{srchStartDate}
	AND OD_YYMM <= #{srchEndDate}

	AND mv.ENT_CODE = #{srchEntCode}

