	)

/* SystemMngMapper.insertAlarmGroupUser : 알림 서비스 수신자 insert */
	INSERT INTO TB_SMS_ALARM_GROUP_USER(
		   GROUP_ID
		  ,SEQ_NO_ID
		  ,ALARM_TYPE
		  ,NAME
		  ,TEL
		  ,EMAIL
		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME
		  ,UPDATE_USER_ID
		  ,UPDATE_DATE_TIME
	)VALUES(
		   #{srchGroupId}
		  ,(SELECT ISNULL(MAX(SEQ_NO_ID), 0) + 1 FROM TB_SMS_ALARM_GROUP_USER WHERE GROUP_ID = #{srchGroupId})
		  ,#{srchAlarmType}
		  ,#{srchName}
		  ,#{srchTel}
		  ,#{srchEmail}
		  ,#{userId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
		  ,#{userId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
	)

