/* SystemMngMapper.updateAlarmGroupUser : 알림 서비스 수신자 update */
	UPDATE TB_SMS_ALARM_GROUP_USER SET
		   NAME = #{srchName}
		  ,TEL = #{srchTel}
		  ,EMAIL = #{srchEmail}
	WHERE GROUP_ID = #{srchGroupId}
	AND SEQ_NO_ID = #{srchSeqNoId}

mapper.select:
/* SystemMngMapper.selectAlarmGroupUserSaveChk : 알림 서비스 수신자 저장 전 체크 */
	SELECT COUNT(GROUP_ID) AS CNT
	FROM TB_SMS_ALARM_GROUP_USER
	WHERE GROUP_ID = #{srchGroupId}
	AND ALARM_TYPE = #{srchAlarmType}


	AND TEL = #{srchTel}


	AND EMAIL = #{srchEmail}



	AND SEQ_NO_ID != #{srchSeqNoId}

/* SystemMngMapper.selectAlarmGroupList : 알림 서비스 리스트 조회 */

	SELECT
		 arm.GROUP_ID
		,arm.GROUP_NAME
		,(SELECT ETC1 FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND CODE = arm.GROUP_ID AND GROUP_CODE = 'ALARM_GROUP') AS SOLUTION
		,(
			SELECT COUNT(GROUP_ID)
			FROM TB_SMS_ALARM_GROUP_USER
			WHERE GROUP_ID = arm.GROUP_ID

			AND REGISTER_DATE_TIME >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})


			AND REGISTER_DATE_TIME < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))


			AND NAME = #{srchName}


			AND TEL = #{srchTel}


			AND EMAIL = #{srchEmail}

		 ) AS USER_COUNT
	FROM TB_SMS_ALARM_GROUP arm

	WHERE arm.GROUP_ID = #{srchGroupId}

/* SystemMngMapper.selectAlarmGroupUserList : 알림 서비스 수신자 리스트 조회 */

	SELECT
		 usr.GROUP_ID
		,(SELECT ETC1 FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND CODE = usr.GROUP_ID AND GROUP_CODE = 'ALARM_GROUP') AS SOLUTION
		,usr.SEQ_NO_ID
		,usr.NAME
		,usr.TEL
		,usr.EMAIL
	FROM TB_SMS_ALARM_GROUP_USER usr
	WHERE usr.GROUP_ID = #{srchGroupId}

	AND usr.REGISTER_DATE_TIME >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})


	AND usr.REGISTER_DATE_TIME < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))


	AND usr.NAME = #{srchName}


	AND usr.TEL = #{srchTel}


	AND usr.EMAIL = #{srchEmail}


	AND usr.ALARM_TYPE = #{srchAlarmType}

/* SystemMngMapper.selectAlimTalkEntList : 알림톡 업체등록정보 List(main) 조회 */
SELECT ENT_CODE , ENT_NAME , SMS_SEND_TEL_NO , SMS_USER_ID , SMS_CID_NUM FROM exps_master.dbo.TB_SMS_ENTERPRISE WHERE 1 = 1
AND ENT_CODE = #{srchEntCode}
AND CONTRACT_DATE >= CONVERT(VARCHAR,#{srchStartDate}, CAST(#{srchDateFormat} AS INT))
AND CONTRACT_DATE <= CONVERT(VARCHAR,#{srchEndDate}, CAST(#{srchDateFormat} AS INT))

/* SystemMngMapper.selectAlimTalkEntTemplateList : 알림톡 업체에 등록된 템플릿 List(sub) 조회 */
SELECT M.ENT_CODE , M.TEMPLATE_SEQ_NO , M.TEMPLATE_TYPE , M.TEMPLATE_CODE , T.TEMPLATE_NAME , M.LABEL_NAME , M.RESEND_MSG_TYPE , M.CREATE_AUTO_YN , M.FINISH_AUTO_YN , M.MSG_TYPE , T.TEMPLATE , T.RESEND_TEMPLATE , T.SUBJECT , T.BUTTON1_TYPE , T.BUTTON1_NAME , T.BUTTON1_URL , T.BUTTON2_TYPE , T.BUTTON2_NAME , T.BUTTON2_URL , T.BUTTON3_TYPE , T.BUTTON3_NAME , T.BUTTON3_URL , T.BUTTON4_TYPE , T.BUTTON4_NAME , T.BUTTON4_URL , T.BUTTON5_TYPE , T.BUTTON5_NAME , T.BUTTON5_URL
FROM TB_MMS_MANAGEMENT M LEFT JOIN exps_master.dbo.TB_MMS_TEMPLATE T ON M.TEMPLATE_TYPE = T.TEMPLATE_TYPE AND M.TEMPLATE_SEQ_NO = T.TEMPLATE_SEQ_NO WHERE M.ENT_CODE = #{srchEntCode}
AND M.TEMPLATE_TYPE = #{srchTemplateType}
AND M.TEMPLATE_SEQ_NO = #{srchTemplateSeqNo}

