	, BUTTON2_URL
	, BUTTON3_TYPE
	, BUTTON3_NAME
	, BUTTON3_URL
	, BUTTON4_TYPE
	, BUTTON4_NAME
	, BUTTON4_URL
	, BUTTON5_TYPE
	, BUTTON5_NAME
	, BUTTON5_URL
	, REGISTER_USER_ID
	, REGISTER_DATE_TIME

   )VALUES(

	#{templateType}
	, ISNULL((SELECT MAX(TEMPLATE_SEQ_NO) FROM TB_MMS_TEMPLATE WHERE TEMPLATE_TYPE = #{templateType}),0) + 1
	, #{templateName}
	, #{templateCode}
	, #{subject}
	, #{template}
