	, #{registerUserId}
	, GETDATE()

   )

/* SystemMngMapper.updateTemplate : 알림톡 알림톡 데이터 수정 */
UPDATE TB_MMS_TEMPLATE SET
	   TEMPLATE_NAME = #{templateName}
	  ,TEMPLATE_CODE = #{templateCode} 
	  ,SUBJECT = #{subject}
	  ,TEMPLATE = #{template}
	  ,RESEND_TEMPLATE = #{resendTemplate}
	  ,BUTTON1_TYPE = #{button1Type}
	  ,BUTTON1_NAME = #{button1Name}
	  ,BUTTON1_URL = #{button1Url}
