mapper.select:
/* SystemMngMapper.selectGridConfigGroupList : 그리드 그룹 목록 조회 */
/* SystemMngMapper.selectGridConfigGroupList : 그리드 그룹 목록 조회 (최근순) */
SELECT GROUP_CODE
FROM TB_SMS_GRID_CONFIGURATION
WHERE ENT_CODE = #{entCode}
  AND   USER_ID  = #{userId}
  AND   GRID_ID  = #{gridId}
  AND   GROUP_CODE IS NOT NULL
  AND   GROUP_CODE <> ''
GROUP BY GROUP_CODE
ORDER BY MAX(REGISTER_DATE_TIME) DESC

mapper.delete:
/* SystemMngMapper.deleteGridConfig : 그리드 환경설정(그룹별) 삭제 */
DELETE FROM TB_SMS_GRID_CONFIGURATION
WHERE ENT_CODE   = #{ENT_CODE}
  AND   USER_ID    = #{USER_ID}
  AND   GRID_ID    = #{GRID_ID}
  AND   GROUP_CODE = #{GROUP_CODE}

mapper.insert:
