INSERT INTO TB_SMS_GRID_CONFIGURATION(
ENT_CODE
,USER_ID
,GRID_ID
,GROUP_CODE
,COL_NAME
,VIEW_YN
,LOCK_YN
,DISPLAY_INDEX
,COL_WIDTH
,REGISTER_USER_ID
,REGISTER_DATE_TIME
,UPDATE_USER_ID
,UPDATE_DATE_TIME
)

	SELECT
	#{item.ENT_CODE}
	,#{item.USER_ID}
	,#{item.GRID_ID}
	,#{item.GROUP_CODE}
	,#{item.COL_NAME}
	,#{item.VIEW_YN}
	,#{item.LOCK_YN}
	,#{item.DISPLAY_INDEX}
	,ISNULL(#{item.COL_WIDTH},'100px')
	,#{item.USER_ID}
	,CONVERT(VARCHAR,DATEADD(hh, cast(#{item.gmtTime} AS int), GETDATE()), 20)
	,#{item.USER_ID}
	,CONVERT(VARCHAR,DATEADD(hh, cast(#{item.gmtTime} AS int), GETDATE()), 20)
